function getTeams(lg,custom){const base={NFL:T_NFL,NBA:T_NBA,MLB:T_MLB,NHL:T_NHL,WNBA:T_WNBA,NCAAF:T_NCAAF,NCAAB:T_NCAAB}[lg]||[];const extra=(custom&&custom[lg])||[];return[...base,...extra.filter(e=>!base.includes(e))];}
function getPlayers(sp,custom,league,roster=NFL_ROSTER){const base=sp==="Golf"?GOLF_P:sp==="Football"&&(!league||league==="NFL")?roster.map(p=>p.name):[];return uniqueNames([...base,...((custom&&custom[sp])||[])]);}

const SPORT_MARKETS={Football:{markets:["Spread","Moneyline","Total","Team Total","1H Spread","1H ML","1H Total","1Q Spread","1Q ML","1Q Total","Player Prop","Alt Spread","Alt Total","Other"]},Basketball:{markets:["Spread","Moneyline","Total","Team Total","1H Spread","1H ML","1H Total","1Q Spread","1Q ML","1Q Total","Player Prop","Alt Spread","Alt Total","Other"]},Baseball:{markets:["Spread","Moneyline","Total","Team Total","1H Spread","1H ML","1H Total","Player Prop","Alt Spread","Alt Total","Other"]},Hockey:{markets:["Spread","Moneyline","Total","Team Total","1P ML","1P Spread","1P Total","Player Prop","Alt Spread","Alt Total","Other"]},Soccer:{markets:["Spread","Moneyline","Total","Team Total","Draw No Bet","Double Chance","Both Teams Score","1H Spread","1H Total","Player Prop","Other"]},Tennis:{markets:["Moneyline","Spread","Total","Set Spread","Set Total","Player Prop","Other"]},MMA:{markets:["Moneyline","Method of Victory","Round Total","Fight to Go Distance","Round Betting","Other"]},Golf:{markets:["Outright Winner","Top 5","Top 10","Top 20","Top 30","Top 40","Matchup","Make Cut","Miss Cut","1st Round Leader","Other"]},Other:{markets:["Spread","Moneyline","Total","Player Prop","Other"]}};
const PROP_STATS={Football:["Pass Yds","Pass TDs","INTs","Rush Yds","Rush Att","Rec Yds","Receptions","Rec TDs","Rush TDs","Anytime TD","Rush+Rec Yds","Completions","Kicking Pts","Tackles","Sacks","Other"],Basketball:["Points","Rebounds","Assists","3-Pointers","Steals","Blocks","Turnovers","Pts+Reb","Pts+Ast","Reb+Ast","Pts+Reb+Ast","Double Double","Other"],Baseball:["Strikeouts","Hits","Home Runs","RBIs","Runs","Bases","Walks","Outs Recorded","Stolen Bases","Other"],Hockey:["Points","Goals","Assists","Shots on Goal","Saves","Blocks","Power Play Pts","Other"],Soccer:["Goals","Assists","Shots","Shots on Target","Tackles","Cards","Other"],Tennis:["Aces","Double Faults","Games Won","Other"]};
function tmpl(s,custom){const base=SPORT_MARKETS[s]||SPORT_MARKETS.Other;const extras=(custom&&custom[s])||[];const extraNames=extras.map(e=>typeof e==="string"?e:e.name).filter(n=>!base.markets.includes(n));return{markets:[...base.markets,...extraNames]};}
function cmBehaviors(custom){const cb={};if(!custom)return cb;Object.values(custom).forEach(arr=>(arr||[]).forEach(e=>{if(typeof e==="object"&&e.name)cb[e.name]={side:!!e.side,line:!!e.line,ou:!!e.ou,player:!!e.player};}));return cb;}
function pstats(s){return PROP_STATS[s]||["Other"];}
function wantsOU(m,cb){if(cb&&cb[m])return!!cb[m].ou;return["Total","Team Total","1H Total","1Q Total","1P Total","Alt Total","Round Total","Set Total","Player Prop"].includes(m);}
function wantsLine(m,cb){if(cb&&cb[m])return!!cb[m].line;return["Spread","Total","Team Total","1H Spread","1H Total","1Q Spread","1Q Total","1P Spread","1P Total","Alt Spread","Alt Total","Set Spread","Set Total","Player Prop","Round Total"].includes(m);}
function wantsSide(m,cb){if(cb&&cb[m])return!!cb[m].side;return["Spread","Moneyline","Team Total","1H Spread","1H ML","1Q Spread","1Q ML","1P ML","1P Spread","Alt Spread","Draw No Bet","Double Chance","Both Teams Score","Method of Victory","1st Round Leader","Other"].includes(m);}
function wantsPlayer(m,cb){if(cb&&cb[m])return!!cb[m].player;return m==="Player Prop"||["Outright Winner","Top 5","Top 10","Top 20","Top 30","Top 40","Make Cut","Miss Cut"].includes(m);}

