  const allFiltered=useMemo(()=>{const list=filters.result?bets.filter(b=>filters.result==="pending"?!b.result:b.result===filters.result):bets;return applyFilters(list);},[bets,filters,applyFilters]);
  const lastBet=bets.length>0?bets[0]:null;
