        {view==="edit"&&editBet&&<BetForm active={view==="edit"} bet={editBet} books={books} holders={holders} tags={tags} settings={settings} lastGolfTourney={lastGolfTourney} customTeams={customTeams} customPlayers={customPlayers} customMarkets={customMarkets} setCustomTeams={setCustomTeams} setCustomPlayers={setCustomPlayers} setCustomMarkets={setCustomMarkets} onSave={b=>{updateBet(editBet.id,b);setView(editBet.result?"history":"open");}} onCancel={()=>setView(editBet.result?"history":"open")} sports={DEFAULT_SPORTS} isEdit/>}
