  const updateUi=patch=>setSettings?.(s=>({...s,ui:{...UI_DEFAULTS,...s.ui,...patch}}));
  useEffect(()=>{setLoaded(50);setScrollTop(0);if(scrollRef.current)scrollRef.current.scrollTop=0;},[filters,activeSort]);
  useEffect(()=>{setScrollTop(0);if(scrollRef.current)scrollRef.current.scrollTop=0;},[rowHeight]);
