const entryNumber = v => v !== null && v !== undefined && String(v).trim() !== "" && Number.isFinite(Number(v));
const uniqueNames = names => [...new Map(names.filter(Boolean).map(n=>[normalizeName(n),n.trim()])).values()];
function newSmartLeg(previous, sport, league, teaser=false){return {id:uid(),smart:true,sport:previous?.sport||sport,league:previous?.league||league,marketType:teaser?"Spread":previous?.marketType||"Spread",team:"",participant:"",propStat:previous?.propStat||"",overUnder:previous?.overUnder||"Over",line:"",selection:"",lineMode:"original"};}
function smartLegLine(leg,teaser,points){
  if(!entryNumber(leg.line))return "";
  const n=Number(leg.line);
  if(!teaser||leg.lineMode==="final")return n;
  return r2(n+(leg.marketType==="Total"?(leg.overUnder==="Under"?1:-1):1)*Number(points));
}
function smartLegText(leg,teaser,points){
  if(!leg.smart)return [leg.selection,leg.line].filter(v=>v!==""&&v!=null).join(" ").trim();
  const line=smartLegLine(leg,teaser,points);
  if(leg.marketType==="Total")return (leg.team||"?")+" "+buildDisplay("Total","",line,leg.overUnder);
  return buildDisplay(leg.marketType,leg.team,line,leg.overUnder,leg.participant,leg.propStat);
}
function validSmartLeg(leg,teaser,points){
  if(!leg.smart)return !!(leg.selection||"").trim();
  if(teaser&&!["Spread","Total"].includes(leg.marketType))return false;
  if(leg.marketType!=="Moneyline"&&!entryNumber(leg.line))return false;
  if(leg.marketType!=="Player Prop"&&!(leg.team||"").trim())return false;
  if(leg.marketType==="Player Prop"&&(!(leg.participant||"").trim()||!leg.propStat))return false;
  return !smartLegText(leg,teaser,points).includes("?");
}
// Composer formats are local UI state; stored odds remain the existing decimal/American fields.
function parseComposerOdds(value,format){const raw=String(value??"").trim();return parseOdds(format==="percent"&&raw&&!raw.endsWith("%")?raw+"%":raw,format==="decimal"?"decimal":"american");}
function formatComposerOdds(decimal,format){return format==="american"?String(calc.decToAmer(decimal)):String(Number((format==="percent"?100/decimal:decimal).toFixed(6)));}
function ComposerSection({title,subtitle,children}){return <section className="composer-section"><header><h2>{title}</h2>{subtitle&&<p className="micro">{subtitle}</p>}</header>{children}</section>;}
function AutoInput({value,onChange,items=[],placeholder,style:sx,id,name,onBlur,"aria-describedby":describedBy,"aria-invalid":invalid,"data-step-first":first}){
  const [open,setOpen]=useState(false),[hi,setHi]=useState(-1),listId=useRef(null);if(!listId.current)listId.current="suggest-"+uid();
  const filtered=useMemo(()=>{if(!value||!items.length)return[];const clean=s=>s.toLowerCase().replace(/[^a-z0-9]/g,"");const v=clean(value);return items.filter(i=>clean(i).includes(v)).sort((a,b)=>Number(clean(b).startsWith(v))-Number(clean(a).startsWith(v))).slice(0,10);},[value,items]);
  const show=open&&filtered.length>0&&value.length>0;
  return <div className="auto-input" style={sx}><input id={id} name={name} data-step-first={first} className={`input ${invalid?"is-error":""}`} aria-label={!id?placeholder:undefined} aria-describedby={describedBy} aria-invalid={invalid} role="combobox" aria-autocomplete="list" aria-expanded={show} aria-controls={show?listId.current:undefined} aria-activedescendant={show&&hi>=0?listId.current+"-"+hi:undefined} autoComplete="off" value={value} placeholder={placeholder} onChange={e=>{onChange(e.target.value);setOpen(true);setHi(-1);}} onFocus={()=>setOpen(true)} onBlur={e=>{onBlur?.(e);setOpen(false);}} onKeyDown={e=>{if(e.key==="Escape"){if(show)e.stopPropagation();setOpen(false);return;}if(!show)return;if(e.key==="ArrowDown"){e.preventDefault();setHi(n=>Math.min(n+1,filtered.length-1));}else if(e.key==="ArrowUp"){e.preventDefault();setHi(n=>Math.max(n-1,0));}else if(e.key==="Enter"&&hi>=0){e.preventDefault();onChange(filtered[hi]);setOpen(false);}}}/>{show&&<div id={listId.current} className="auto-options" role="listbox" aria-label="Suggestions">{filtered.map((item,i)=><div id={listId.current+"-"+i} key={item} role="option" aria-selected={i===hi} onPointerDown={e=>{e.preventDefault();onChange(item);setOpen(false);}} className={i===hi?"is-active":""}>{item}</div>)}</div>}</div>;
}
function SmartLegEditor({leg,index,teaser,points,sports,customTeams,customPlayers,roster,onChange,onRemove,onDuplicate}){
  const sport=leg.sport||"Football",league=leg.league||"NFL",prop=leg.marketType==="Player Prop",[touched,setTouched]=useState({});
  const players=uniqueNames([...getPlayers(sport,customPlayers,league,roster),...(league==="NFL"?roster.map(p=>p.name):[])]);
  const change=(key,value)=>onChange({...leg,[key]:value});
  return <fieldset className="smart-leg" onBlurCapture={e=>{if(e.target.name)setTouched(p=>({...p,[e.target.name]:true}));}}><legend>Leg {index+1}</legend><div className="leg-actions"><Button size="sm" variant="ghost" onClick={onDuplicate}>Duplicate</Button>{onRemove&&<Button size="sm" variant="ghost" icon="close" aria-label={"Remove leg "+(index+1)} onClick={onRemove}/>}</div>
    {!leg.smart?<div className="composer-grid"><Field label="Saved selection"><input className="input" value={leg.selection||""} onChange={e=>change("selection",e.target.value)}/></Field><Field label="Line"><input className="input" value={leg.line??""} onChange={e=>change("line",e.target.value)}/></Field><p className="micro">Existing selection kept as entered.</p></div>:<>
      <div className="composer-grid"><Field label="Leg sport"><select className="select" disabled={teaser} value={sport} onChange={e=>onChange({...newSmartLeg(null,e.target.value,sports.find(s=>s.name===e.target.value)?.leagues[0]||"",teaser),id:leg.id})}>{sports.map(s=><option key={s.name}>{s.name}</option>)}</select></Field><Field label="Leg league"><select className="select" disabled={teaser} value={league} onChange={e=>change("league",e.target.value)}>{(sports.find(s=>s.name===sport)?.leagues||[]).map(l=><option key={l}>{l}</option>)}</select></Field></div>
      <Field label="Leg market"><select className="select" value={leg.marketType} onChange={e=>onChange({...leg,marketType:e.target.value,line:""})}>{(teaser?[...(!["Spread","Total"].includes(leg.marketType)?[leg.marketType]:[]),"Spread","Total"]:["Spread","Moneyline","Total","Player Prop"]).map(m=><option key={m}>{m}</option>)}</select></Field>
      {teaser&&!["Spread","Total"].includes(leg.marketType)&&<p className="composer-note tone-caution">Choose Spread or Total for this teaser leg.</p>}
      <Field label={prop?"Leg player":leg.marketType==="Total"?"Game / matchup":"Leg team"} error={touched.pick&&!(prop?leg.participant:leg.team)?.trim()?"Enter a selection.":undefined}><AutoInput name="pick" value={prop?leg.participant:leg.team} onChange={v=>{const p=roster.find(p=>p.name===v);onChange({...leg,[prop?"participant":"team"]:v,...(prop&&!leg.propStat&&p&&league==="NFL"?{propStat:p.position==="QB"?"Pass Yds":p.position==="RB"||p.position==="FB"?"Rush Yds":p.position==="K"?"Kicking Pts":"Rec Yds"}:{})});}} items={prop?players:getTeams(league,customTeams)} placeholder={prop?"Start typing a player…":leg.marketType==="Total"?"Chiefs vs Bills":"Start typing a team…"}/></Field>
      {prop&&<Field label="Leg stat" error={touched.stat&&!leg.propStat?"Choose a statistic.":undefined}><select name="stat" className="select" value={leg.propStat} onChange={e=>onChange({...leg,propStat:e.target.value,...(e.target.value==="Anytime TD"?{line:"0.5",overUnder:"Over"}:{})})}><option value="">Choose stat…</option>{pstats(sport).map(s=><option key={s}>{s}</option>)}</select></Field>}
      <div className="composer-grid">{(prop||leg.marketType==="Total")&&<Field label="Leg direction"><select className="select" value={leg.overUnder} onChange={e=>change("overUnder",e.target.value)}><option>Over</option><option>Under</option></select></Field>}{leg.marketType!=="Moneyline"&&<Field label={teaser&&leg.lineMode!=="final"?"Original line":"Leg line"} error={touched.line&&!entryNumber(leg.line)?"Enter a valid line.":undefined}><input className="input mono" name="line" inputMode="decimal" value={leg.line} onChange={e=>change("line",e.target.value)}/></Field>}</div>
      {teaser&&<label className="composer-check"><input type="checkbox" checked={leg.lineMode==="final"} onChange={e=>change("lineMode",e.target.checked?"final":"original")}/>I entered the adjusted line</label>}
      <p className="micro leg-preview">{teaser?"Adjusted selection: ":""}{smartLegText(leg,teaser,points)}</p>
    </>}
  </fieldset>;
}

